!function(){"use strict";tinymce.PluginManager.add("collectivebbcodesnippets",e=>{const t=document.body.dataset.portalUrl;fetch(`${t}/@bbcodesnippets_enabled`,{headers:{Accept:"application/json"}}).then(e=>e.json()).then(t=>{t.forEach(t=>{e.ui.registry.addMenuItem(`bbcs${t.name}`,{text:`${t.name} (${t.snippet})`,onAction:()=>((e,t)=>{const n=e.selection.getContent({format:"text"});let o=t.replace("$TEXT",n);o=o.replace("$CURSOR",""),e.selection.setContent(o)})(e,t.template)})})}).catch(e=>{console.error("BBCode Snippets: Failed to load snippets",e)})})}();
